import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"夬","description":"周易正义 - 夬","frontmatter":{"title":"夬","description":"周易正义 - 夬"},"headers":[],"relativePath":"zh/classics/zhengyi/043.md","filePath":"zh/classics/zhengyi/043.md"}'),l={name:"zh/classics/zhengyi/043.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>泽天夬</p></blockquote><blockquote><p>卦辞：扬于王庭，孚号有厉；告自邑，不利即戎；利有攸往。</p></blockquote><blockquote><p>彖曰：夬，决也，刚决柔也。健而说，决而和。扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。</p></blockquote><h1 id="夬" tabindex="-1">夬 <a class="header-anchor" href="#夬" aria-label="Permalink to “夬”">​</a></h1><p>王弼：夬与剥反者也。剥以柔变刚，至於刚几尽。夬以刚决柔，如剥之消刚。刚陨则君子道消，柔消则小人道陨。君子道消，则刚正之德不可得直道而用，刑罚之威不可得坦然而行。“扬于王庭”，其道公也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>“夬扬于王庭”至“利有攸往”。○正义曰：夬，决也。此阴消阳息之卦也。阳长至五，五阳共决一阴，故名为“夬”也。“扬于王庭”者，明行决断之法，夬以刚决柔，施之於人，则是君子决小人也。王庭是百官所在之处，以君子决小人，故可以显然发扬决断之事於王者之庭，示公正而无私隐也，故曰“扬于王庭”也。“孚号有厉”者，号，号令也。行决之法，先须号令。夬以刚决柔，则是用明信之法而宣其号令，如此即柔邪者危，故曰“孚号有厉”也。以刚制断，行令於邑可也。若用刚即戎，尚力取胜，为物所疾，以此用师，必有不利，故曰“告自邑，不利即戎”。虽“不利即戎”，然刚德不长，则柔邪不消。故阳爻宜有所往，夬道乃成，故曰“利有攸往”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="夬-决也-刚决柔也。健而说-决而和。-​" tabindex="-1">夬，决也，刚决柔也。健而说，决而和。 ​ <a class="header-anchor" href="#夬-决也-刚决柔也。健而说-决而和。-​" aria-label="Permalink to “夬，决也，刚决柔也。健而说，决而和。 ​”">​</a></h3><p>王弼：“健而说”，则“决而和”矣。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>“《彖》曰”至“决而和”。○正义曰：夬，决也。“刚决柔”者，此就爻释卦名也。“健而说，决而和”者，此就二体之义，明决而能和，乾健而兑说，健则能决，说则能和，故曰“决而和”也。</p><h3 id="扬于王庭-柔乘五刚也。-​" tabindex="-1">“扬于王庭”，柔乘五刚也。 ​ <a class="header-anchor" href="#扬于王庭-柔乘五刚也。-​" aria-label="Permalink to ““扬于王庭”，柔乘五刚也。 ​”">​</a></h3><p>王弼：刚德齐长，一柔为逆，众所同诛，而无忌者也。故可“扬于王庭”。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此因一阴而居五阳之上，释行决之法。以刚德齐长，一柔为逆，无所同诛，诛而无忌也，故曰“扬于王庭”。言所以得显然“扬于王庭”者，只谓柔乘五刚也。</p><h3 id="孚号有厉-其危乃光也。-​" tabindex="-1">“孚号有厉”，其危乃光也。 ​ <a class="header-anchor" href="#孚号有厉-其危乃光也。-​" aria-label="Permalink to ““孚号有厉”，其危乃光也。 ​”">​</a></h3><p>王弼：刚正明信以宣其令，则柔邪者危，故曰“其危乃光也”。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：以明信而宣号令，即柔邪者危厉，危厉之理，分明可见，故曰“其危乃光也”。</p><h3 id="告自邑-不利即戎-所尚乃穷也。-​" tabindex="-1">“告自邑，不利即戎”，所尚乃穷也。 ​ <a class="header-anchor" href="#告自邑-不利即戎-所尚乃穷也。-​" aria-label="Permalink to ““告自邑，不利即戎”，所尚乃穷也。 ​”">​</a></h3><p>王弼：以刚断制，告令可也。“告自邑”，谓行令於邑也。用刚即戎，尚力取胜也。尚力取胜，物所同疾也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：刚克之道，不可常行。若专用威猛，以此即戎，则便为尚力取胜，即是决而不和，其道穷矣。行决所以惟“告自邑，不利即戎”者，只谓所尚乃穷故也。</p><h3 id="利有攸往-刚长乃终也。-​" tabindex="-1">“利有攸往”，刚长乃终也。 ​ <a class="header-anchor" href="#利有攸往-刚长乃终也。-​" aria-label="Permalink to ““利有攸往”，刚长乃终也。 ​”">​</a></h3><p>王弼：刚德愈长，柔邪愈消，故“利有攸往”，道乃成也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：终成也，刚长柔消，夬道乃成也。</p><h2 id="《象》曰-泽上於天-夬。君子以施禄及下-居德则忌。-​" tabindex="-1">《象》曰：泽上於天，夬。君子以施禄及下，居德则忌。 ​ <a class="header-anchor" href="#《象》曰-泽上於天-夬。君子以施禄及下-居德则忌。-​" aria-label="Permalink to “《象》曰：泽上於天，夬。君子以施禄及下，居德则忌。 ​”">​</a></h2><p>王弼：“泽上於天”，夬之象也。“泽上於天”，必来下润，“施禄及下”之义也。《夬》者，明法而决断之象也。忌止也。法明断严，不以慢，故“居德”以明禁也。施而能严，严而能施，健而能说，决而能和，美之道也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>“《象》曰”至“居德则忌”。○正义曰：“泽上於天，夬”者，泽性润下，虽复“泽上於天”，决来下润，此事必然，故是“夬”之象也。“君子以施禄及下，居德则忌”者，忌，禁也。“决”有二义，《象》则泽来润下，《彖》则明法决断，所以君子法此夬义。威惠兼施，虽复施禄及下，其在身居德，复须明其禁令，合於健而能说，决而能和，故曰“君子以施禄及下，居德则忌”也。</p><h2 id="初九-壮于前趾-往不胜-为咎。居健之初-为决之始-宜审其策-以行其事。壮其前趾-往而不胜-宜其咎也。-​" tabindex="-1">初九：壮于前趾，往不胜，为咎。居健之初，为决之始，宜审其策，以行其事。壮其前趾，往而不胜，宜其咎也。 ​ <a class="header-anchor" href="#初九-壮于前趾-往不胜-为咎。居健之初-为决之始-宜审其策-以行其事。壮其前趾-往而不胜-宜其咎也。-​" aria-label="Permalink to “初九：壮于前趾，往不胜，为咎。居健之初，为决之始，宜审其策，以行其事。壮其前趾，往而不胜，宜其咎也。 ​”">​</a></h2><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：初九居夬之初，当须审其筹策，然后乃往。而体健处下，徒欲果决壮健，前进其趾，以此而往，必不克胜，非决之谋，所以“为咎”，故曰“初九，壮于前趾，往不胜，为咎”也。</p><h3 id="《象》曰-不胜而往-咎也。不胜之理-在往前也。-​" tabindex="-1">《象》曰：不胜而往，咎也。不胜之理，在往前也。 ​ <a class="header-anchor" href="#《象》曰-不胜而往-咎也。不胜之理-在往前也。-​" aria-label="Permalink to “《象》曰：不胜而往，咎也。不胜之理，在往前也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：《经》称“往不胜。为咎”，象云“不胜而往，咎”翻其文者，盖暴虎冯河，孔子所忌，谬於用壮，必无胜理。孰知不胜，果决而往，所以致於咎过。故注云“不胜之理，在往前”也。</p><h2 id="九二-惕号-莫夜有戎-勿恤。居健履中-以斯决事-能审已度而不疑者也。故虽有惕惧号呼-莫夜有戎-不忧不惑-故-勿恤-也。-​" tabindex="-1">九二：惕号，莫夜有戎，勿恤。居健履中，以斯决事，能审已度而不疑者也。故虽有惕惧号呼，莫夜有戎，不忧不惑，故“勿恤”也。 ​ <a class="header-anchor" href="#九二-惕号-莫夜有戎-勿恤。居健履中-以斯决事-能审已度而不疑者也。故虽有惕惧号呼-莫夜有戎-不忧不惑-故-勿恤-也。-​" aria-label="Permalink to “九二：惕号，莫夜有戎，勿恤。居健履中，以斯决事，能审已度而不疑者也。故虽有惕惧号呼，莫夜有戎，不忧不惑，故“勿恤”也。 ​”">​</a></h2><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：九二体健居中，能决其事，而无疑惑者也。虽复有人惕惧号呼，语之云莫夜必有戎卒来害已，能番已度，不惑不忧，故“勿恤”也。</p><h3 id="《象》曰-有戎勿恤-得中道也。-​" tabindex="-1">《象》曰：“有戎勿恤”，得中道也。 ​ <a class="header-anchor" href="#《象》曰-有戎勿恤-得中道也。-​" aria-label="Permalink to “《象》曰：“有戎勿恤”，得中道也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“得中道”者，决事而得中道，故不以有戎为忧，故云“得中道”也。</p><h2 id="九三-壮于頄-有凶。君子夬夬-独行-遇雨若濡。而愠-无咎。頄-面权也-谓上六也。最处体上-故曰-权-也。剥之六三-以应阳为善。夫刚长则君子道兴-阴盛则小人道长。然则处阴长而助阳则善-处刚长而助柔则凶矣。夬为刚长-而三独应上六-助於小人-是以凶也。君子处之-必能弃夫情累-决之不疑-故曰-夬夬-也。若不与众阳为群-而独行殊志-应於小人-则受其困焉。-遇雨若濡-有恨而无所咎也。-​" tabindex="-1">九三：壮于頄，有凶。君子夬夬，独行，遇雨若濡。而愠，无咎。頄，面权也，谓上六也。最处体上，故曰“权”也。剥之六三，以应阳为善。夫刚长则君子道兴，阴盛则小人道长。然则处阴长而助阳则善，处刚长而助柔则凶矣。夬为刚长，而三独应上六，助於小人，是以凶也。君子处之，必能弃夫情累，决之不疑，故曰“夬夬”也。若不与众阳为群，而独行殊志，应於小人，则受其困焉。“遇雨若濡”，有恨而无所咎也。 ​ <a class="header-anchor" href="#九三-壮于頄-有凶。君子夬夬-独行-遇雨若濡。而愠-无咎。頄-面权也-谓上六也。最处体上-故曰-权-也。剥之六三-以应阳为善。夫刚长则君子道兴-阴盛则小人道长。然则处阴长而助阳则善-处刚长而助柔则凶矣。夬为刚长-而三独应上六-助於小人-是以凶也。君子处之-必能弃夫情累-决之不疑-故曰-夬夬-也。若不与众阳为群-而独行殊志-应於小人-则受其困焉。-遇雨若濡-有恨而无所咎也。-​" aria-label="Permalink to “九三：壮于頄，有凶。君子夬夬，独行，遇雨若濡。而愠，无咎。頄，面权也，谓上六也。最处体上，故曰“权”也。剥之六三，以应阳为善。夫刚长则君子道兴，阴盛则小人道长。然则处阴长而助阳则善，处刚长而助柔则凶矣。夬为刚长，而三独应上六，助於小人，是以凶也。君子处之，必能弃夫情累，决之不疑，故曰“夬夬”也。若不与众阳为群，而独行殊志，应於小人，则受其困焉。“遇雨若濡”，有恨而无所咎也。 ​”">​</a></h2><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>“九三壮于頄”至“无咎”。○正义曰：“壮于頄，有凶”者，頄，面权也，谓上六也。言九三处夬之时，独应上六，助於小人，是以凶也。若剥之六三，处阴长之时而应上，是助阳为善。今九三处刚长之时，独助阴为凶也。“君子夬夬”者，君子之人，若於此时，能弃其情累，不受於应，在於决断而无滞，是“夬夬”也。“独行，遇雨若濡，有愠无咎”者，若不能决断，殊於众阳，应於小人，则受濡湿其衣，自为怨恨，无咎责於人，故曰“有愠无咎”也。</p><h3 id="《象》曰-君子夬夬-终无咎也。-​" tabindex="-1">《象》曰：“君子夬夬”，终无咎也。 ​ <a class="header-anchor" href="#《象》曰-君子夬夬-终无咎也。-​" aria-label="Permalink to “《象》曰：“君子夬夬”，终无咎也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：众阳决阴，独与上六相应，是有咎也。若能“夬夬”，决之不疑，则“终无咎”矣。然则象云“无咎”，自释“君子夬夬”，非经之“无咎”也。</p><h2 id="九四-臀无肤-其行次且。牵羊悔亡-闻言不信。不刚而进-非已所据-必见侵伤-失其所安-故-臀无肤-其行次且-也。羊者-抵狠难移之物-谓五也。五为夬主-非下所侵。若牵於五-则可得-悔亡-而已。刚亢不能纳言-自任所处-闻言不信以斯而行-凶可知矣。-​" tabindex="-1">九四：臀无肤，其行次且。牵羊悔亡，闻言不信。不刚而进，非已所据，必见侵伤，失其所安，故“臀无肤，其行次且”也。羊者，抵狠难移之物，谓五也。五为夬主，非下所侵。若牵於五，则可得“悔亡”而已。刚亢不能纳言，自任所处，闻言不信以斯而行，凶可知矣。 ​ <a class="header-anchor" href="#九四-臀无肤-其行次且。牵羊悔亡-闻言不信。不刚而进-非已所据-必见侵伤-失其所安-故-臀无肤-其行次且-也。羊者-抵狠难移之物-谓五也。五为夬主-非下所侵。若牵於五-则可得-悔亡-而已。刚亢不能纳言-自任所处-闻言不信以斯而行-凶可知矣。-​" aria-label="Permalink to “九四：臀无肤，其行次且。牵羊悔亡，闻言不信。不刚而进，非已所据，必见侵伤，失其所安，故“臀无肤，其行次且”也。羊者，抵狠难移之物，谓五也。五为夬主，非下所侵。若牵於五，则可得“悔亡”而已。刚亢不能纳言，自任所处，闻言不信以斯而行，凶可知矣。 ​”">​</a></h2><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>“九四臀无肤”至“闻言不信”。○正义曰：“臀无肤，其行次且”者，九四据下三阳，位又不正，下刚而进，必见侵伤侵伤，则居不得安，若“臀无肤”矣。次且行不前进也。臀之无肤，居既失安，行亦不进，故曰“臀无肤，其行次且”也。“牵羊悔亡，闻言不信”者，羊者，抵狠难移之物，谓五也。居尊当位，为夬之主，下不敢侵。若牵於五，则可得悔亡，故曰“牵羊悔亡”。然四亦是刚阳，各亢所处，虽复闻牵羊之言，不肯信服事於五，故曰“闻言不信也”。</p><h3 id="《象》曰-其行次且-位不当也。-闻言不信-聪不明也。同於噬嗑灭耳之-凶-。-​" tabindex="-1">《象》曰：“其行次且”，位不当也。“闻言不信”，聪不明也。同於噬嗑灭耳之“凶”。 ​ <a class="header-anchor" href="#《象》曰-其行次且-位不当也。-闻言不信-聪不明也。同於噬嗑灭耳之-凶-。-​" aria-label="Permalink to “《象》曰：“其行次且”，位不当也。“闻言不信”，聪不明也。同於噬嗑灭耳之“凶”。 ​”">​</a></h3><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>“无不明也”。○正义曰：“聪不明”者，聪，听也。良由听之不明，故闻言不信也。○注“同於噬嗑灭耳之凶”。○正义曰：四既闻言不信，不肯牵系於五，则必被侵克致凶。而《经》无凶文，《象》称“聪不明”者，与《噬嗑》上九辞同，彼以不明释凶，知此亦为凶也。</p><h2 id="九五-苋陆夬夬-中行无咎。苋陆-草之柔脆者也。决之至易-故曰-夬夬-也。夬之为义-以刚决柔-以君子除小人者也。而五处尊位-最比小人-躬自决者也。以至尊而敌至贱-虽其克胜-未足多也。处中而行-足以免咎而已-未足光也。-​" tabindex="-1">九五：苋陆夬夬，中行无咎。苋陆，草之柔脆者也。决之至易，故曰“夬夬”也。夬之为义，以刚决柔，以君子除小人者也。而五处尊位，最比小人，躬自决者也。以至尊而敌至贱，虽其克胜，未足多也。处中而行，足以免咎而已，未足光也。 ​ <a class="header-anchor" href="#九五-苋陆夬夬-中行无咎。苋陆-草之柔脆者也。决之至易-故曰-夬夬-也。夬之为义-以刚决柔-以君子除小人者也。而五处尊位-最比小人-躬自决者也。以至尊而敌至贱-虽其克胜-未足多也。处中而行-足以免咎而已-未足光也。-​" aria-label="Permalink to “九五：苋陆夬夬，中行无咎。苋陆，草之柔脆者也。决之至易，故曰“夬夬”也。夬之为义，以刚决柔，以君子除小人者也。而五处尊位，最比小人，躬自决者也。以至尊而敌至贱，虽其克胜，未足多也。处中而行，足以免咎而已，未足光也。 ​”">​</a></h2><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>“九五”至“无咎”。○正义曰：“苋陆，草之柔脆者也。夬之为义，以刚决柔，以君子除小人者也。”五处尊位，为夬之主，亲决上六，决之至易也，如决苋草然，故曰“苋陆夬夬”也。但以至尊而敌於至贱，虽其克胜，不足贵也。特以中行之故，才得无咎，故曰“中行无咎”。○注“苋陆，草之柔脆者”。○正义曰：“苋陆，草之柔脆”者，子夏《传》云：“苋陆，木根，草茎，刚下柔上也。”马融、郑玄、王肃皆云“苋陆，一名商陆”，皆以苋陆为一。黄遇云：“苋，人苋也。陆，商陆也。”以苋陆为二。案：《注》直云“草之柔脆”者，亦以为一同於子夏等也。</p><h3 id="《象》曰-中行无咎-中未光也。-​" tabindex="-1">《象》曰：“中行无咎”，中未光也。 ​ <a class="header-anchor" href="#《象》曰-中行无咎-中未光也。-​" aria-label="Permalink to “《象》曰：“中行无咎”，中未光也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“中未光”者，虽复居中而行，以其亲决上六，以尊敌卑，未足以为光大也。</p><h2 id="上六-无号-终有凶。处夬之极-小人在上-君子道长-无所共弃-故非号咷所能延也。-​" tabindex="-1">上六：无号，终有凶。处夬之极，小人在上，君子道长，无所共弃，故非号咷所能延也。 ​ <a class="header-anchor" href="#上六-无号-终有凶。处夬之极-小人在上-君子道长-无所共弃-故非号咷所能延也。-​" aria-label="Permalink to “上六：无号，终有凶。处夬之极，小人在上，君子道长，无所共弃，故非号咷所能延也。 ​”">​</a></h2><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：上六，居夬之极，以小人而居群阳之上，众共弃也。君子道长，小人必凶。非号咷所免，故禁其号咷，曰“无号终有凶”也。</p><h3 id="《象》曰-无号-之-凶-终不可长也。-​" tabindex="-1">《象》曰：“无号”之“凶”，终不可长也。 ​ <a class="header-anchor" href="#《象》曰-无号-之-凶-终不可长也。-​" aria-label="Permalink to “《象》曰：“无号”之“凶”，终不可长也。 ​”">​</a></h3><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“终不可长”者，长，延也。凶危若此，非号咷所能延，故曰“终不可长也”。</p>',68)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
